# The twelve vehicle subsystems of the Change Prediction Method (Clarkson, Simons, Eckert 2004)
# as used by cost/cpm_engine.py. Read by the backend effort engine and by
# frontend/scripts/build-cpm.py (frontend/content/cpm.json).
#
# ASSUMPTIONS, NOT CALIBRATED (effort rule 50): every weight, likelihood and impact below is the
# team's estimate from public cost breakdowns (Thunder Said Energy 2024, Bosch 2020) and the
# back-test against eight documented BMW decisions. BMW engineering or a mentor may change any
# value; every change is logged by the engine.
#
# weight:      share of a new vehicle's development effort; the twelve weights sum to 100.
# links:       direct propagation links from this subsystem: likelihood that a change here forces
#              a change in the target (0 to 1) and the share of the target's design work redone (0 to 1).
# certification_trigger: a change with own impact of 0.3 or more re-runs crash, emission or range
#              tests and adds the certification add-on.
method:
  name: Change Prediction Method
  reference: Clarkson, Simons, Eckert (2004), Predicting Change Propagation in Complex Design, Journal of Mechanical Design 126(5)
  url: https://oro.open.ac.uk/18626
  engine: cost/cpm_engine.py
  basis: assumption, not calibrated
  weight_sources:
    - Thunder Said Energy (2024), EV vs ICE cost breakdown by component (drivetrain about 30 to 36 % of vehicle cost)
    - Bosch (2020), electronics share of premium vehicle component cost (16 % in 2020, 35 % expected by 2025)
  thresholds:
    adapt_below_percent: 15
    new_generation_from_percent: 50
  certification_add_on_percent: 12
  carryover_likelihood_multiplier: 0.3
  max_path_length: 3


