        "http://127.0.0.1/admin",
        "http://169.254.169.254/latest/meta-data/",
        "http://10.0.0.5/",
        "http://[::1]/",
        "http://inside.example/",  # a public name with a private address
        "http://unknown.example/",
        "file:///etc/passwd",
        "ftp://8.8.8.8/",
    ):
